1	#ifndef SG_FUSED_SM90_FUSED_DECODER_MEGAKERNEL_CUH_
2	#define SG_FUSED_SM90_FUSED_DECODER_MEGAKERNEL_CUH_
3	// ============================================================================
4	// csrc/fused/sm_90/fused_decoder_megakernel.cuh — PHASE 1 of the TRUE L3 fused
5	// megakernel. ONE persistent kernel per training step runs the REAL transformer-
6	// decoder forward+backward AND the AdamW optimizer math, separated only by
7	// in-kernel grid barriers — real model math, real optimizer math, ZERO
8	// intermediate kernel launches.
9	//
10	// This composes:
11	//   * the REAL decoder fwd/bwd stages (model_stages_decoder.cuh — transcribed
12	//     line-for-line from the verified PyTorch oracle, asserted bit-identical to
13	//     autograd, and structurally mirrored on CPU),
14	//   * the existing persistent substrate (megakernel_common.cuh: task queue, the
15	//     hand-built sense-reversing GridBarrier),
16	//   * the existing REAL optimizer tail (opt_components.cuh::apply_optimizer<Opt>).
17	//
18	// STAGE / BARRIER LAYOUT (5 phases, 4 grid barriers — see the per-stage comments):
19	//   P0  zero the per-CTA grad-partial workspace + per-CTA loss slots (each CTA
20	//       zeroes its OWN slice — no cross-CTA contention, no host memset needed).
21	//   --- grid barrier (B0): all partials zeroed before any accumulation ---
22	//   P1  BATCH-PARALLEL fwd+bwd: each CTA owns a FIXED contiguous batch slice
23	//       (by blockIdx.x), processes its samples ONE AT A TIME (CTA-cooperative),
24	//       accumulating each sample's weight-grad contribution into the CTA's OWN
25	//       partial buffer (gw + cta*total) with a single-owner-thread-per-element
26	//       rule (no atomics → deterministic), and summing its slice's NLL (fp32)
27	//       into the CTA's loss slot.
28	//   --- grid barrier (B1): all CTAs' partials + loss complete ---
29	//   P2  DETERMINISTIC cross-CTA reduce: sum partial[0..nCTA) in ASCENDING CTA
30	//       index into the global `grad` buffer (no float atomics; the per-element
31	//       summation ORDER is fixed, so the work-steal queue MAY pick who reduces
32	//       which element-range — determinism is in the order, not the picker). The
33	//       loss slots are summed in fp64 → one device float (loss/B), by CTA 0.
34	//   --- grid barrier (B2): reduced grad ready in global ---
35	//   P3  the existing apply_optimizer<AdamW> tail consumes the reduced grad
36	//       in-place over the flat param (work-steal queue over the 30 tensors).
37	//   (no barrier after P3 — kernel exits; the step is complete.)
38	//
39	// HONESTY: no placeholder math anywhere on this path. fp32 compute is the
40	// correctness baseline; a bf16-compute follow-up would be a flag defaulting to
41	// THIS fp32 path (not yet wired — see the report).
42	// ============================================================================
43	
44	#include "csrc/fused/megakernel_common.cuh"
45	#include "csrc/fused/sm_90/opt_components.cuh"
46	#include "csrc/fused/sm_90/decoder_layout.cuh"
47	#include "csrc/fused/sm_90/model_stages_decoder.cuh"
48	#include "csrc/backends/cuda/sm_90/warp_specialize.cuh"
49	
50	#include <cuda_runtime.h>
51	#include <cstdint>
52	#include <cassert>
53	
54	namespace sg { namespace fused { namespace sm90 {
55	
56	// Rebase a FusedOptState's per-element state pointers to a parameter-tensor
57	// slice at `off` within the flat [m|v|extra] layout. Per-TENSOR fields (the
58	// NeuralGrok psi MLP weights) and all scalars pass through unchanged.
59	template <OptId Opt>
60	__device__ __forceinline__ FusedOptState
61	rebase_state(const FusedOptState& s, int64_t off) {
62	    FusedOptState t = s;  // scalars + per-tensor pointers copy as-is
63	    if (t.exp_avg)    t.exp_avg    += off;
64	    if (t.exp_avg_sq) t.exp_avg_sq += off;
65	    if (t.ema)        t.ema        += off;
66	    if (t.sam_dir)    t.sam_dir    += off;
67	    if (t.s_track)    t.s_track    += off;
68	    if (t.mu)         t.mu         += off;
69	    if (t.orth)       t.orth       += off;
70	    if (t.smart_grad) t.smart_grad += off;
71	    return t;
72	}
73	
74	// The L3-REAL decoder megakernel needs the token path + a grad-partial workspace
75	// in addition to the FuseTier::{L1,L3} ABI. We keep it a SEPARATE kernel +
76	// launcher (not folded into fused_megakernel) so the surrogate path is untouched.
77	//
78	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
79	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
80	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
81	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
82	// total == kDecTotalElems == 422755.
83	
84	struct DecoderTokenCtx {
85	    const int* tokens;   // [B, kSeq] int32 token ids in [0, kVocab)
86	    const int* targets;  // [B]       int32 target ids
87	    int        B;        // batch size (full-batch in the race ≈ 4191)
88	    float*     workspace; // grad partials + loss partials + reduced loss
89	    float*     loss_out;  // device float the kernel writes the mean loss into
90	};
91	
92	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
93	//    threads/CTA. The smem holds ONE DecSampleSmem (≈42 KB, < 48 KB static cap —
94	//    no dynamic-smem opt-in, so the occupancy≥1 guard with dynamicSMemBytes=0 in
95	//    the launcher is unchanged). ────────────────────────────────────────────────
96	// sizes/offsets are NOT host-passed: the per-tensor numel/offset live in the
97	// generated __constant__ tables kDecSizes/kDecOffsets (decoder_layout.cuh), so
98	// the reduce + optimizer phases read them directly. This also lets the host side
99	// (dispatch.cpp) avoid building any layout tensors.
100	template <OptId Opt>
101	__global__ void __launch_bounds__(256)
102	fused_decoder_megakernel(PersistentContext ctx,
103	                         float* __restrict__ params,
104	                         DecoderTokenCtx tok,
105	                         float* __restrict__ grad,        // reduced grad [total]
106	                         float lr, int step, FusedOptState st) {
107	    __shared__ DecSampleSmem sm;
108	    GridBarrier bar = ctx.barrier();
109	    const int cta = blockIdx.x;
110	    const int nCTA = (int)ctx.n_ctas;
111	    const int64_t total = kDecTotalElems;
112	    float* my_partial = tok.workspace + (int64_t)cta * total;   // this CTA's dW
113	    float* loss_part = tok.workspace + (int64_t)nCTA * total;   // [nCTA]
114	
115	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
116	    const int wg = threadIdx.x / 128;
117	    // warp-specialize prims live in sg::sm90::wgs (this file is sg::fused::sm90)
118	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
119	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
120	
121	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
122	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
123	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
124	    bar.sync();   // B0
125	
126	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
127	    DecWeights w = dec_bind(params);
128	    DecGrad g = dec_bind_grad(my_partial);
129	    // Even split with remainder to the low CTAs (contiguous, deterministic).
130	    const int B = tok.B;
131	    const int base = B / nCTA, rem = B % nCTA;
132	    const int b0 = cta * base + (cta < rem ? cta : rem);
133	    const int cnt = base + (cta < rem ? 1 : 0);
134	    const int b1 = b0 + cnt;
135	    __shared__ int tok_s[dec::kSeq];   // this sample's token ids (broadcast)
136	    __shared__ int tgt_s;
137	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
138	    for (int b = b0; b < b1; ++b) {
139	        if (threadIdx.x < dec::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * dec::kSeq + threadIdx.x];
140	        if (threadIdx.x == 0) tgt_s = tok.targets[b];
141	        __syncthreads();
142	        float nll = dec_forward_sample(w, tok_s, tgt_s, &sm);
143	        dec_backward_sample(w, g, tok_s, tgt_s, B, &sm);
144	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
145	        __syncthreads();   // sample boundary: all grad writes done before reuse
146	    }
147	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
148	    bar.sync();   // B1: all CTA partials + loss slots complete
149	
150	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
151	    //    (one task = one parameter tensor; sum its elements across CTAs in
152	    //    ascending CTA index). The summation ORDER (ascending cta) is fixed, so
153	    //    the result is deterministic regardless of which CTA grabs the task. ────
154	    {
155	        __shared__ int task_slot;
156	        TaskQueue q = ctx.queue();
157	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
158	             t = q.next_block(&task_slot)) {
159	            const int n = kDecSizes[t];
160	            const int64_t off = (int64_t)kDecOffsets[t];
161	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
162	                float acc = 0.0f;
163	                // ascending CTA index → fixed fp32 summation order (deterministic).
164	                for (int c = 0; c < nCTA; ++c)
165	                    acc += tok.workspace[(int64_t)c * total + off + i];
166	                grad[off + i] = acc;
167	            }
168	        }
169	    }
170	    // Loss reduction (fp64 ordered) by CTA 0 only — the 1e-5 loss rel-tol is the
171	    // tightest gate; fp32 atomic-summing ~4191 terms can miss it.
172	    if (cta == 0 && threadIdx.x == 0) {
173	        double s = 0.0;
174	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
175	        float mean = (float)(s / (double)B);
176	        *tok.loss_out = mean;
177	    }
178	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
179	
180	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
181	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
182	    st.lr = lr;
183	    {
184	        __shared__ int task_slot;
185	        TaskQueue q = ctx.queue();
186	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
187	             t = q.next_block(&task_slot)) {
188	            const int n = kDecSizes[t];
189	            const int64_t off = (int64_t)kDecOffsets[t];
190	            const FusedOptState ts = rebase_state<Opt>(st, off);
191	            float* __restrict__ p = params + off;
192	            const float* __restrict__ gg = grad + off;
193	            for (int i = threadIdx.x; i < n; i += blockDim.x)
194	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
195	        }
196	    }
197	}
198	
199	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
200	//    Mirrors launch_fused_megakernel's hang-freedom contract: occupancy≥1 or
201	//    refuse (the GridBarrier rendezvous of n_ctas CTAs can never complete if a
202	//    CTA can't be placed). Zeroes the barrier+task counters per launch. ─────────
203	template <OptId Opt>
204	cudaError_t launch_fused_decoder_megakernel(
205	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
206	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
207	    int dev = 0;
208	    cudaError_t err = cudaGetDevice(&dev);
209	    if (err != cudaSuccess) return err;
210	    int n_sms = 0;
211	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
212	    if (err != cudaSuccess) return err;
213	
214	    int occ = 0;
215	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
216	        &occ, (const void*)&fused_decoder_megakernel<Opt>, 256,
217	        /*dynamicSMemBytes=*/0);
218	    if (err != cudaSuccess) return err;
219	    // Hang-freedom: at least one CTA per SM must be resident or the grid barrier
220	    // can never be satisfied. The L3-REAL kernel uses ≈42 KB static smem + a high
221	    // register count; if it cannot place one block/SM, REFUSE rather than hang.
222	    assert(occ >= 1 &&
223	           "fused_decoder_megakernel: 0 blocks/SM — GridBarrier would hang. The "
224	           "decoder smem (~42KB) + regs exceed one-block-per-SM occupancy; "
225	           "reduce footprint or fall back to the L1 per-op path.");
226	    if (occ < 1) return cudaErrorLaunchOutOfResources;
227	
228	    const unsigned launch_ctas = (unsigned)n_sms;
229	    ctx.n_ctas = launch_ctas;
230	
231	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
232	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
233	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
234	
235	    dim3 grid(launch_ctas), block(256);
236	    fused_decoder_megakernel<Opt><<<grid, block, 0, stream>>>(
237	        ctx, params, tok, grad, lr, step, st);
238	    return cudaGetLastError();
239	}
240	
241	}}} // namespace sg::fused::sm90
242	
243	#endif  // SG_FUSED_SM90_FUSED_DECODER_MEGAKERNEL_CUH_
