1	#ifndef SG_FUSED_SM90_FUSED_VIT_MEGAKERNEL_CUH_
2	#define SG_FUSED_SM90_FUSED_VIT_MEGAKERNEL_CUH_
3	// ============================================================================
4	// csrc/fused/sm_90/fused_vit_megakernel.cuh — PHASE 2 of the TRUE L3 fused
5	// megakernel. ONE persistent kernel per training step runs the REAL Vision-
6	// Transformer forward+backward AND the optimizer math, separated only by
7	// in-kernel grid barriers — real model math, real optimizer math, ZERO
8	// intermediate kernel launches. The ViT counterpart of PHASE 1's
9	// fused_decoder_megakernel.cuh.
10	//
11	// This composes:
12	//   * the REAL ViT fwd/bwd stages (model_stage_vit.cuh — transcribed
13	//     line-for-line from the verified PyTorch oracle, asserted bit-identical to
14	//     autograd, and structurally mirrored on CPU),
15	//   * the existing persistent substrate (megakernel_common.cuh: task queue, the
16	//     hand-built sense-reversing GridBarrier),
17	//   * the existing REAL optimizer tail (opt_components.cuh::apply_optimizer<Opt>).
18	//
19	// STAGE / BARRIER LAYOUT (identical to the decoder — 5 phases, B0..B2 + the
20	// fused sync_reset; see the per-stage comments):
21	//   P0  each CTA zeroes its OWN grad-partial slice + loss slot.
22	//   --- grid barrier B0 ---
23	//   P1  BATCH-PARALLEL fwd+bwd: each CTA owns a FIXED contiguous batch slice (by
24	//       blockIdx.x), processes its samples ONE AT A TIME (CTA-cooperative),
25	//       accumulating each sample's weight-grad into the CTA's partial with a
26	//       single-owner-thread-per-element rule (no atomics → deterministic), and
27	//       sums its slice's NLL (fp32).
28	//   --- grid barrier B1 ---
29	//   P2  DETERMINISTIC cross-CTA reduce: sum partial[0..nCTA) in ASCENDING CTA
30	//       index into the global grad (no float atomics; order fixed → reuses the
31	//       work-steal queue to pick WHO reduces which tensor). Loss: fp64 ordered
32	//       sum → loss/B → a device float the host reads back (by CTA 0).
33	//   --- grid barrier B2 (sync_reset: also resets the queue for P3) ---
34	//   P3  the REAL apply_optimizer<Opt> tail consumes the reduced grad in place.
35	//
36	// DYNAMIC SHARED MEMORY (the ONE thing the decoder path did NOT need): ViT's
37	// per-sample VitSampleSmem is ≈ 183.67 KB (seq=17), which CANNOT be a static
38	// __shared__ (48 KB cap). So this kernel declares `extern __shared__` and the
39	// LAUNCHER must, all three of: (1) cudaFuncSetAttribute(kernel,
40	// cudaFuncAttributeMaxDynamicSharedMemorySize, sizeof(VitSampleSmem)); (2) pass
41	// dynamicSMemBytes=sizeof(VitSampleSmem) to cudaOccupancyMaxActiveBlocksPerMSM
42	// (so the occ≥1 hang-freedom check is honest); (3) pass it at <<<...>>>. Missing
43	// ANY of these makes the kernel silently fail to launch — see the launcher.
44	//
45	// HONESTY: no placeholder math anywhere on this path. fp32 compute is the
46	// correctness baseline; a bf16-compute follow-up would be a flag defaulting to
47	// THIS fp32 path (not yet wired — see the report / TODO in model_stage_vit.cuh).
48	// ============================================================================
49	
50	#include "csrc/fused/megakernel_common.cuh"
51	#include "csrc/fused/sm_90/opt_components.cuh"
52	#include "csrc/fused/sm_90/vit_layout.cuh"
53	#include "csrc/fused/sm_90/model_stage_vit.cuh"
54	#include "csrc/backends/cuda/sm_90/warp_specialize.cuh"
55	
56	#include <cuda_runtime.h>
57	#include <cstdint>
58	#include <cassert>
59	
60	namespace sg { namespace fused { namespace sm90 {
61	
62	// Compile-time guard: the byte budget the launcher uses (sizeof(VitSampleSmem))
63	// MUST equal the literal the layout header documents + bounds-checks (227 KB cap).
64	static_assert(sizeof(VitSampleSmem) == (size_t)vit_layout_check::kVitSampleSmemBytes,
65	              "fused_vit_megakernel: sizeof(VitSampleSmem) != the documented "
66	              "kVitSampleSmemBytes in vit_layout.cuh — update both together.");
67	
68	// Rebase a FusedOptState's per-element state pointers to a parameter-tensor slice
69	// at `off` within the flat [m|v|extra] layout. Per-TENSOR fields and all scalars
70	// pass through unchanged. (Identical to the decoder's rebase_state; redefined here
71	// under a vit_ name so this header stays self-contained — the decoder file is
72	// owned by a sibling agent and must not be included.)
73	template <OptId Opt>
74	__device__ __forceinline__ FusedOptState
75	vit_rebase_state(const FusedOptState& s, int64_t off) {
76	    FusedOptState t = s;  // scalars + per-tensor pointers copy as-is
77	    if (t.exp_avg)    t.exp_avg    += off;
78	    if (t.exp_avg_sq) t.exp_avg_sq += off;
79	    if (t.ema)        t.ema        += off;
80	    if (t.sam_dir)    t.sam_dir    += off;
81	    if (t.s_track)    t.s_track    += off;
82	    if (t.mu)         t.mu         += off;
83	    if (t.orth)       t.orth       += off;
84	    if (t.smart_grad) t.smart_grad += off;
85	    return t;
86	}
87	
88	// The L3-REAL ViT megakernel needs the FLOAT patch path + a grad-partial
89	// workspace. Kept a SEPARATE kernel + launcher (not folded into the surrogate
90	// fused_megakernel) so the surrogate path is untouched.
91	//
92	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
93	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
94	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
95	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
96	// total == kVitTotalElems == 418017.
97	struct ViTInputCtx {
98	    const float* patches;  // [B, kNPatch, kPatch] fp32 image patches
99	    const int*   targets;  // [B]                  int32 target ids in [0,kVocab)
100	    int          B;        // batch size
101	    float*       workspace; // grad partials + loss partials + reduced loss
102	    float*       loss_out;  // device float the kernel writes the mean loss into
103	};
104	
105	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
106	//    threads/CTA. VitSampleSmem (~183.67 KB) lives in DYNAMIC smem (extern). ────
107	// sizes/offsets are NOT host-passed: per-tensor numel/offset live in the
108	// __constant__ tables kVitSizes/kVitOffsets (vit_layout.cuh), read directly by
109	// the reduce + optimizer phases.
110	template <OptId Opt>
111	__global__ void __launch_bounds__(256)
112	fused_vit_megakernel(PersistentContext ctx,
113	                     float* __restrict__ params,
114	                     ViTInputCtx in,
115	                     float* __restrict__ grad,        // reduced grad [total]
116	                     float lr, int step, FusedOptState st) {
117	    extern __shared__ char vit_smem_raw[];
118	    VitSampleSmem& sm = *reinterpret_cast<VitSampleSmem*>(vit_smem_raw);
119	    GridBarrier bar = ctx.barrier();
120	    const int cta = blockIdx.x;
121	    const int nCTA = (int)ctx.n_ctas;
122	    const int64_t total = kVitTotalElems;
123	    float* my_partial = in.workspace + (int64_t)cta * total;   // this CTA's dW
124	    float* loss_part = in.workspace + (int64_t)nCTA * total;   // [nCTA]
125	
126	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
127	    const int wg = threadIdx.x / 128;
128	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
129	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
130	
131	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
132	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
133	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
134	    bar.sync();   // B0
135	
136	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
137	    VitWeights w = vit_bind(params);
138	    VitGrad g = vit_bind_grad(my_partial);
139	    const int B = in.B;
140	    const int base = B / nCTA, rem = B % nCTA;
141	    const int b0 = cta * base + (cta < rem ? cta : rem);
142	    const int cnt = base + (cta < rem ? 1 : 0);
143	    const int b1 = b0 + cnt;
144	    __shared__ int tgt_s;
145	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
146	    const int patch_elems = vit::kNPatch * vit::kPatch;   // 16*49 = 784
147	    for (int b = b0; b < b1; ++b) {
148	        // Load this sample's float patches into smem (cooperative).
149	        const float* src = in.patches + (int64_t)b * patch_elems;
150	        for (int i = threadIdx.x; i < patch_elems; i += blockDim.x)
151	            sm.patch[i / vit::kPatch][i % vit::kPatch] = src[i];
152	        if (threadIdx.x == 0) tgt_s = in.targets[b];
153	        __syncthreads();
154	        float nll = vit_forward_sample(w, tgt_s, &sm);
155	        vit_backward_sample(w, g, tgt_s, B, &sm);
156	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
157	        __syncthreads();   // sample boundary: all grad writes done before reuse
158	    }
159	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
160	    bar.sync();   // B1: all CTA partials + loss slots complete
161	
162	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
163	    //    (one task = one parameter tensor; sum its elements across CTAs in
164	    //    ascending CTA index). Summation ORDER (ascending cta) is fixed →
165	    //    deterministic regardless of which CTA grabs the task. ─────────────────
166	    {
167	        __shared__ int task_slot;
168	        TaskQueue q = ctx.queue();
169	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
170	             t = q.next_block(&task_slot)) {
171	            const int n = kVitSizes[t];
172	            const int64_t off = (int64_t)kVitOffsets[t];
173	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
174	                float acc = 0.0f;
175	                for (int c = 0; c < nCTA; ++c)
176	                    acc += in.workspace[(int64_t)c * total + off + i];
177	                grad[off + i] = acc;
178	            }
179	        }
180	    }
181	    // Loss reduction (fp64 ordered) by CTA 0 only — the loss rel-tol is the
182	    // tightest gate; fp32 atomic-summing many terms can miss it.
183	    if (cta == 0 && threadIdx.x == 0) {
184	        double s = 0.0;
185	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
186	        float mean = (float)(s / (double)B);
187	        *in.loss_out = mean;
188	    }
189	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
190	
191	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 32
192	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
193	    st.lr = lr;
194	    {
195	        __shared__ int task_slot;
196	        TaskQueue q = ctx.queue();
197	        for (int t = q.next_block(&task_slot); t < kVitNumTensors;
198	             t = q.next_block(&task_slot)) {
199	            const int n = kVitSizes[t];
200	            const int64_t off = (int64_t)kVitOffsets[t];
201	            const FusedOptState ts = vit_rebase_state<Opt>(st, off);
202	            float* __restrict__ p = params + off;
203	            const float* __restrict__ gg = grad + off;
204	            for (int i = threadIdx.x; i < n; i += blockDim.x)
205	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
206	        }
207	    }
208	}
209	
210	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
211	//    Mirrors launch_fused_decoder_megakernel's hang-freedom contract (occupancy≥1
212	//    or refuse), PLUS the DYNAMIC-SMEM opt-in that the ViT footprint requires:
213	//      (1) cudaFuncSetAttribute(MaxDynamicSharedMemorySize, sizeof(VitSampleSmem))
214	//      (2) dynamicSMemBytes = sizeof(VitSampleSmem) in the occ≥1 query
215	//      (3) dynamicSMemBytes = sizeof(VitSampleSmem) at <<<...>>>
216	//    All three are mandatory; missing any one makes the launch silently fail. ───
217	template <OptId Opt>
218	cudaError_t launch_fused_vit_megakernel(
219	        PersistentContext ctx, float* params, ViTInputCtx in,
220	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
221	    int dev = 0;
222	    cudaError_t err = cudaGetDevice(&dev);
223	    if (err != cudaSuccess) return err;
224	    int n_sms = 0;
225	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
226	    if (err != cudaSuccess) return err;
227	
228	    const int dyn_smem = (int)sizeof(VitSampleSmem);   // ≈ 188080 B (183.67 KB)
229	
230	    // (1) Opt in to >48 KB dynamic smem for THIS kernel. Without this the launch
231	    //     fails with cudaErrorInvalidValue (the static 48 KB default applies).
232	    err = cudaFuncSetAttribute(
233	        (const void*)&fused_vit_megakernel<Opt>,
234	        cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_smem);
235	    if (err != cudaSuccess) return err;
236	
237	    // (2) Occupancy with the REAL dynamic-smem request (hang-freedom is honest).
238	    int occ = 0;
239	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
240	        &occ, (const void*)&fused_vit_megakernel<Opt>, 256,
241	        /*dynamicSMemBytes=*/dyn_smem);
242	    if (err != cudaSuccess) return err;
243	    // At least one CTA per SM must be resident or the grid barrier can never be
244	    // satisfied. ~183.67 KB dynamic smem fits the sm_90 227 KB cap at occ=1 (the
245	    // persistent megakernel is one-CTA-per-SM by design); if it cannot place one
246	    // block/SM, REFUSE rather than hang.
247	    assert(occ >= 1 &&
248	           "fused_vit_megakernel: 0 blocks/SM — GridBarrier would hang. The ViT "
249	           "per-sample smem (~184KB dynamic) + regs exceed one-block-per-SM "
250	           "occupancy on this device; reduce footprint or fall back to eager.");
251	    if (occ < 1) return cudaErrorLaunchOutOfResources;
252	
253	    const unsigned launch_ctas = (unsigned)n_sms;
254	    ctx.n_ctas = launch_ctas;
255	
256	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
257	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
258	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
259	
260	    // (3) Launch WITH the dynamic-smem byte count.
261	    dim3 grid(launch_ctas), block(256);
262	    fused_vit_megakernel<Opt><<<grid, block, dyn_smem, stream>>>(
263	        ctx, params, in, grad, lr, step, st);
264	    return cudaGetLastError();
265	}
