279	// Per-(device, n) reusable scratch for fused_step. The barrier counters and the
280	// `acts` proxy were previously reallocated (and `acts` memset over the full
281	// param size) on EVERY dispatch; sizes/offsets are constant for a given n.
282	// We persist them keyed by (device_index, n) and only reset the mutable parts
283	// (zero the 3 barrier counters + the acts buffer) per step. Behavior is
284	// identical — same zero-initialized scratch handed to the launcher — but the
285	// allocations/the full-size memset of sizes/offsets happen once per shape.
286	struct FusedScratch {
287	 torch::Tensor g_next;       // int32 [1]
288	 torch::Tensor g_arrived;    // int32 [1] (reinterpreted as unsigned)
289	 torch::Tensor g_generation; // int32 [1] (reinterpreted as unsigned)
290	 torch::Tensor sizes;        // int32 [1] = n  (constant per n)
291	 torch::Tensor offsets;      // int32 [1] = 0  (constant)
292	 torch::Tensor acts;         // float [numel(params)] proxy buffer
293	};
294	
295	// Keyed by (device_index, n). n disambiguates differing param shapes on the
296	// same device; acts is sized to params.numel() (== n here, single flat tensor).
297	inline FusedScratch& fused_scratch_for(const torch::Tensor& params, int64_t n) {
298	 static std::unordered_map<long long, FusedScratch> cache;
299	 const long long dev_idx =
300	 params.device().is_cuda() ? static_cast<long long>(params.device().index())
301	 : -1LL;
302	 const long long key = (dev_idx << 40) ^ static_cast<long long>(n);
303	 auto it = cache.find(key);
304	 if (it == cache.end()) {
305	 auto opts_i =
306	 torch::TensorOptions().device(params.device()).dtype(torch::kInt32);
307	 FusedScratch s;
308	 s.g_next = torch::zeros({1}, opts_i);
309	 s.g_arrived = torch::zeros({1}, opts_i);
310	 s.g_generation = torch::zeros({1}, opts_i);
311	 s.sizes = torch::full({1}, n, opts_i); // constant for this n
312	 s.offsets = torch::zeros({1}, opts_i); // constant
313	 s.acts = torch::zeros_like(params);
314	 it = cache.emplace(key, std::move(s)).first;
315	 } else {
316	 // Reset only the mutable scratch; sizes/offsets are invariant for this n.
317	 it->second.g_next.zero_();
318	 it->second.g_arrived.zero_();
319	 it->second.g_generation.zero_();
320	 it->second.acts.zero_();
321	 }
322	 return it->second;
323	}
324	#endif
