327	// PHASE-1 decoder L3-REAL: the flat param element count for the small decoder
328	// (vocab=99,d=128,heads=4,layers=2,seq=4). MUST equal
329	// sg::fused::sm90::kDecTotalElems — that device-side constant is NOT visible in
330	// this HOST-compiled TU (it lives in the device-only decoder_layout.cuh), so we
331	// mirror the literal here and cross-check it against params.numel() at the call
332	// site (a mismatch fails loudly). The .cu's static_asserts guard the device side.
333	constexpr int64_t kDecoderTotalElems = 422755;
334	constexpr int     kDecoderSeq        = 4;   // mirror of SG_DEC_SEQ
335	
336	// PHASE-1 decoder L3-REAL scratch: per-CTA grad-partial workspace + barrier
337	// counters + a reduced-grad buffer. The workspace is nCTA*total grad partials +
338	// nCTA loss partials; sized for nCTA = #SMs (the launcher pins one CTA per SM).
339	// The per-tensor sizes/offsets are NOT built here — the kernel reads the
340	// generated __constant__ kDecSizes/kDecOffsets tables directly. Persisted + reset
341	// per step (the big workspace is zeroed IN-KERNEL by phase P0; the host only
342	// resets the barrier/task counters here).
343	struct DecoderScratch {
344	 torch::Tensor g_next;        // int32 [1]
345	 torch::Tensor g_arrived;     // int32 [1] (unsigned-reinterpreted)
346	 torch::Tensor g_generation;  // int32 [1] (unsigned-reinterpreted)
347	 torch::Tensor workspace;     // float [nCTA*total + nCTA] partials + loss slots
348	 int n_ctas = 0;
349	};
350	
351	inline DecoderScratch& decoder_scratch_for(const torch::Tensor& params) {
352	 static std::unordered_map<long long, DecoderScratch> cache;
353	 const long long dev_idx =
354	 params.device().is_cuda() ? static_cast<long long>(params.device().index())
355	 : -1LL;
356	 const long long key = dev_idx;   // one decoder shape per device (fixed total)
357	 auto it = cache.find(key);
358	 const int64_t total = kDecoderTotalElems;
359	 if (it == cache.end()) {
360	 int dev = params.device().is_cuda() ? params.device().index() : 0;
361	 int n_sms = 1;
362	 cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
363	 auto opts_i =
364	 torch::TensorOptions().device(params.device()).dtype(torch::kInt32);
365	 auto opts_f =
366	 torch::TensorOptions().device(params.device()).dtype(torch::kFloat32);
367	 DecoderScratch s;
368	 s.g_next = torch::zeros({1}, opts_i);
369	 s.g_arrived = torch::zeros({1}, opts_i);
370	 s.g_generation = torch::zeros({1}, opts_i);
371	 // The reduced grad is now routed through the ABI `grad` tensor (exposed to the
372	 // caller for per-tensor parity); no internal grad scratch needed.
373	 // workspace: nCTA*total partials + nCTA loss slots. Zeroed in-kernel (P0);
374	 // allocate (not zero) — the in-kernel P0 + the loss reduce overwrite it.
375	 s.workspace = torch::empty({(int64_t)n_sms * total + n_sms}, opts_f);
376	 s.n_ctas = n_sms;
377	 it = cache.emplace(key, std::move(s)).first;
378	 } else {
379	 it->second.g_next.zero_();
380	 it->second.g_arrived.zero_();
381	 it->second.g_generation.zero_();
382	 }
383	 return it->second;
384	}
385	#endif
