    ViTInputCtx in;
    in.patches   = patches;
    in.targets   = targets;
    in.B         = B;
    in.workspace = workspace;
    in.loss_out  = loss_out;

    return launch_fused_vit_megakernel<OptId::AdamW>(
        ctx, params, in, grad, lr, step, st, stream);
