// csrc/fused/sm_90/_mamba_fwd_probe.cu — DIAGNOSTIC harness (NOT part of the
// shipped extension; this file is excluded from setup.py's build and is here only
// to pin the field-level read-before-write in mb_forward_sample on real silicon).
//
// It runs ONE mb_forward_sample on a single CTA (256 threads, dynamic smem opt-in)
// over caller-supplied weights+tokens, then copies the WHOLE MambaSampleSmem back
// to host so a Python driver can diff each cached forward field against the oracle
// in stage order and find the FIRST partially-garbage buffer (the writer/reader
// stride seam). Build standalone:
//   nvcc -O2 -std=c++17 -arch=sm_90a -I<repo-root> _mamba_fwd_probe.cu -o /tmp/probe
//
// Inputs (binary float32 little-endian files): params [259425], tokens int32 [8].
// Output: the full MambaSampleSmem as float32 to stdout (or a file).
#include "csrc/fused/sm_90/model_stage_mamba3.cuh"
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <vector>
#include <cuda_runtime.h>

using namespace sg::fused::sm90;

__global__ void __launch_bounds__(256)
probe_kernel(const float* params, const int* tokens, int target,
             float* smem_out, float* nll_out) {
    extern __shared__ char raw[];
    MambaSampleSmem& sm = *reinterpret_cast<MambaSampleSmem*>(raw);
    __shared__ int tok_s[mb::kSeq];
    if (threadIdx.x < mb::kSeq) tok_s[threadIdx.x] = tokens[threadIdx.x];
    __syncthreads();
    MambaWeights w = mb_bind(params);
    float nll = mb_forward_sample(w, tok_s, target, &sm);
    if (threadIdx.x == 0) *nll_out = nll;
    // Dump the whole struct (as floats) so the host can slice fields by offset.
    const int n = (int)kMambaSmemFloats;
    const float* smf = reinterpret_cast<const float*>(&sm);
    for (int i = threadIdx.x; i < n; i += blockDim.x) smem_out[i] = smf[i];
}

static std::vector<float> read_f32(const char* path, size_t n) {
    std::vector<float> v(n);
    FILE* f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); exit(2); }
    size_t got = fread(v.data(), sizeof(float), n, f); fclose(f);
    if (got != n) { fprintf(stderr, "short read %s: %zu/%zu\n", path, got, n); exit(2); }
    return v;
}

int main(int argc, char** argv) {
    if (argc < 5) { fprintf(stderr, "usage: probe params.bin tokens.bin target out.bin\n"); return 2; }
    const int64_t total = kMambaTotalElems;
    auto params = read_f32(argv[1], (size_t)total);
    // tokens stored as float32 (bit-pattern of int32) for simplicity of the driver.
    auto toks_f = read_f32(argv[2], (size_t)mb::kSeq);
    int target = atoi(argv[3]);
    std::vector<int> toks(mb::kSeq);
    for (int i = 0; i < mb::kSeq; ++i) toks[i] = (int)(toks_f[i] + 0.5f);

    float *d_params, *d_smem, *d_nll; int* d_tok;
    const int smn = (int)kMambaSmemFloats;
    cudaMalloc(&d_params, total * sizeof(float));
    cudaMalloc(&d_tok, mb::kSeq * sizeof(int));
    cudaMalloc(&d_smem, smn * sizeof(float));
    cudaMalloc(&d_nll, sizeof(float));
    cudaMemcpy(d_params, params.data(), total * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_tok, toks.data(), mb::kSeq * sizeof(int), cudaMemcpyHostToDevice);

    const int dyn = (int)kMambaSmemBytes;
    cudaFuncSetAttribute((const void*)&probe_kernel,
        cudaFuncAttributeMaxDynamicSharedMemorySize, dyn);
    probe_kernel<<<1, 256, dyn>>>(d_params, d_tok, target, d_smem, d_nll);
    cudaError_t e = cudaDeviceSynchronize();
    if (e != cudaSuccess) { fprintf(stderr, "kernel err: %s\n", cudaGetErrorString(e)); return 3; }

    std::vector<float> smem(smn); float nll = 0;
    cudaMemcpy(smem.data(), d_smem, smn * sizeof(float), cudaMemcpyDeviceToHost);
    cudaMemcpy(&nll, d_nll, sizeof(float), cudaMemcpyDeviceToHost);
    fprintf(stderr, "nll=%.6f\n", nll);
    FILE* out = fopen(argv[4], "wb");
    fwrite(smem.data(), sizeof(float), smn, out); fclose(out);
    return 0;
}

